import java.sql.DriverManager;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        String url = "jdbc:mysql://localhost/testdb";
        String user = "user";
        String password = "password";

        try {
            // No longer vulnerable to SQL injection attacks
            PreparedStatement stmt = DriverManager.getConnection(url, user, password).prepareStatement("SELECT * FROM users WHERE name = ?");
